namespace Vessel.Domain.Proxy;

/// <summary>Where a proxy configuration version came from.</summary>
public enum ProxyConfigurationSource
{
    /// <summary>Generated by Vessel from the routes on the server (<c>vessel-routes.yml</c>).</summary>
    Generated = 0,

    /// <summary>A user-managed dynamic configuration file (see <see cref="ProxyDynamicConfiguration" />).</summary>
    UserDynamic = 1,

    /// <summary>A restore of an earlier version; links to it through <c>RestoredFromId</c>.</summary>
    Restore = 2
}
